// Custom Worker entry (decision 004): OpenNext's fetch handler plus a Cron Trigger handler.
// OpenNext builds .open-next/worker.js; wrangler bundles this file around it.
import { instanceSettings } from "@gitwork/db";
import { openD1 } from "@gitwork/db/d1";
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

export default {
  fetch: handler.fetch,

  async scheduled(_controller, env, ctx) {
    ctx.waitUntil(
      (async () => {
        const { db } = openD1(env.DB);
        await db
          .insert(instanceSettings)
          .values({ key: "cron_last_run", value: new Date().toISOString() })
          .onConflictDoUpdate({ target: instanceSettings.key, set: { value: new Date().toISOString() } });
      })(),
    );
  },
} satisfies ExportedHandler<CloudflareEnv>;

// @ts-expect-error: generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
